25	fn map_reason_to_change_source(
26	    reason: &BumpReason,
27	    id: &callisto_model::PackageId,
28	    to: &callisto_model::Version,
29	    outcome: &crate::cascade::CascadeOutcome,
30	    agg: &crate::aggregate::Aggregation,
31	) -> Option<ChangeSource> {
32	    match reason {
33	        BumpReason::FixedGroupUnion { group } => Some(ChangeSource::GroupUnion {
34	            group: group.clone(),
35	            kind: GroupKind::Fixed,
36	        }),
37	        BumpReason::LinkedGroupUnion { group } => Some(ChangeSource::GroupUnion {
38	            group: group.clone(),
39	            kind: GroupKind::Linked,
40	        }),
41	        // Listed from `CascadeOutcome::dependency_updates`, which covers every bumped dependency, not just the first.
42	        BumpReason::Cascade { .. } => None,
43	        BumpReason::PeerEscalation { via, .. } => {
44	            let dep_to = outcome.targets.get(via).cloned().unwrap_or_else(|| to.clone());
45	            Some(ChangeSource::PeerEscalation {
46	                dependency: via.clone(),
47	                to: dep_to,
48	            })
49	        }
50	        BumpReason::Inference { commits, .. } => match agg.inference_commits.get(id).and_then(|c| c.first()) {
51	            Some((sha, subject)) => Some(ChangeSource::Commit {
52	                sha: sha.clone(),
53	                subject: subject.clone(),
54	            }),
55	            None => Some(ChangeSource::Changeset {
56	                filename: String::new(),
57	                summary: format!("Inferred version bump ({commits} commit(s))"),
58	            }),
59	        },
60	        _ => None,
61	    }
62	}
