64	/// One "Dependency updates" entry per bumped dependency `id` was updated for, at the version it actually reached.
65	fn dependency_update_entries(
66	    id: &callisto_model::PackageId,
67	    severity: Severity,
68	    outcome: &crate::cascade::CascadeOutcome,
69	) -> Vec<ChangelogEntry> {
70	    let Some(updates) = outcome.dependency_updates.get(id) else {
71	        return Vec::new();
72	    };
73	    updates
74	        .iter()
75	        .filter_map(|(dependency, dep_kind)| {
76	            let to = outcome.targets.get(dependency)?.clone();
77	            Some(ChangelogEntry {
78	                severity,
79	                source: ChangeSource::DependencyUpdate {
80	                    dependency: dependency.clone(),
81	                    dep_kind: *dep_kind,
82	                    to,
83	                },
84	            })
85	        })
86	        .collect()
87	}
