89	/// The GitHub repository compare links point to: the configured `[release] forge-repository`, else `origin`'s. No remote
90	/// or a remote that is not on github.com means no link, not an error.
91	fn changelog_repository<R: CommandRunner, D: DependencyResolver>(
92	    ws: &Workspace<'_, R, D>,
93	) -> Option<callisto_model::GitHubRepository> {
94	    ws.config
95	        .product_release
96	        .as_ref()
97	        .and_then(|release| release.forge_repository.clone())
98	        .or_else(|| {
99	            crate::commands::release::optional_git_remote(&ws.root, ws.runner)
100	                .ok()
101	                .flatten()
102	                .and_then(|remote| remote.github_repository)
103	        })
104	}
