106	/// `reference` as a URL path segment. A tag template may use `#`, `?` or `%`, which would turn the rest of the compare
107	/// range into a fragment or a query; `/`, `@`, `+` and `:` are fine in a path and git refs use them.
108	fn encode_ref(reference: &str) -> String {
109	    reference.bytes().fold(String::new(), |mut out, byte| {
110	        if byte.is_ascii_alphanumeric() || b"-._~/@+:".contains(&byte) {
111	            out.push(char::from(byte));
112	        } else {
113	            out.push_str(&format!("%{byte:02X}"));
114	        }
115	        out
116	    })
117	}
