119	/// The header facts for `id`'s section. A compare link needs a known repository and a tag on the previous version.
120	fn changelog_style<R: CommandRunner, D: DependencyResolver>(
121	    ws: &Workspace<'_, R, D>,
122	    repository: Option<&callisto_model::GitHubRepository>,
123	    tags: &crate::TagIndex,
124	    id: &callisto_model::PackageId,
125	    from: &callisto_model::Version,
126	    to: &callisto_model::Version,
127	    date: Option<&str>,
128	) -> ChangelogStyle {
129	    let compare_url = repository
130	        .zip(crate::commands::release_decision::tag_of_version(tags, id, from))
131	        .map(|(repository, previous)| {
132	            let next = tags.template(id).render(to);
133	            format!(
134	                "https://github.com/{}/compare/{}...{}",
135	                repository.as_slug(),
136	                encode_ref(&previous.to_string()),
137	                encode_ref(&next.to_string())
138	            )
139	        });
140	    ChangelogStyle {
141	        layout: ws.config.changelog_layout,
142	        date: date.map(str::to_owned),
143	        compare_url,
144	    }
145	}
