147	/// `plan_version` with changelog sections dated `date` (`YYYY-MM-DD`); `None` leaves the date off.
148	pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
149	    ws: &Workspace<'_, R, D>,
150	    inference: &I,
151	    opts: &VersionOptions,
152	) -> Result<VersionPlan, GraphError> {
153	    plan_version_dated(ws, inference, opts, None)
154	}
