156	pub fn plan_version_dated<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
157	    ws: &Workspace<'_, R, D>,
158	    inference: &I,
159	    opts: &VersionOptions,
160	    date: Option<&str>,
161	) -> Result<VersionPlan, GraphError> {
162	    let base_versions = ws.base_versions()?;
163	    let tags = ws.tags()?;
164	    let repository = changelog_repository(ws);
165	
166	    let pre_path = ws.root.join(ws.config.pre_json_path());
167	    let pre_text = callisto_model::strict_fs::read_optional(&pre_path).map_err(|e| GraphError::PreJsonRead {
168	        path: pre_path.clone(),
169	        message: e.to_string(),
170	    })?;
171	    let (pre_state, pre_json_original_text) = if let Some(text) = pre_text {
172	        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
173	        let state = ws.resolve_pre_state_from_json(state, &text)?;
174	        (Some(state), Some(text))
175	    } else {
176	        (None, None)
177	    };
178	
179	    let mut agg = aggregate(
180	        &ws.graph,
181	        &ws.identity,
182	        &ws.config,
183	        ws.git_access(),
184	        tags,
185	        &base_versions,
186	        pre_state.as_ref(),
187	        inference,
188	    )?;
189	
190	    // PreMode::Exit: seed a Patch for every pre-release package so `bump_target` finalizes it though the changesets were consumed.
191	    if let Some(ref pre) = pre_state
192	        && pre.mode == callisto_model::format::PreMode::Exit
193	    {
194	        for (id, ver) in &base_versions {
195	            if ver.is_prerelease() {
196	                agg.severities.entry(id.clone()).or_insert(Severity::Patch);
197	                agg.reasons
198	                    .entry(id.clone())
199	                    .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
200	            }
201	        }
202	    }
203	
204	    let input = CascadeInput {
205	        graph: &ws.graph,
206	        groups: &ws.config.groups,
207	        cfg: &ws.config.cascade,
208	        seed: &agg.severities,
209	        reasons: &agg.reasons,
210	        named_by: &agg.named_by,
211	        base: &base_versions,
212	        pre: pre_state.as_ref(),
213	        tags,
214	        identity: &ws.identity,
215	    };
216	
217	    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
218	    let group_check = crate::groups::pre_mutation_checks(&ws.config.groups, &base_versions, tags, &napi, &ws.root)?;
219	
220	    let outcome = run_cascade(input)?;
221	
222	    let mut bumps = Vec::new();
223	    let mut changelog_writes = Vec::new();
224	
225	    // PERF-006: build a map once so each lookup inside the loop is O(1)
226	    // instead of O(N) (the previous packages().find() call).
227	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
228	
229	    for (id, &sev) in &outcome.severities {
230	        if sev == Severity::None {
231	            continue;
232	        }
233	        let pkg = pkg_map
234	            .get(id)
235	            .copied()
236	            .expect("every bumped package is in the workspace");
237	        let from = base_versions.get(id).cloned().ok_or_else(|| {
238	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
239	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
240	                field: "version",
241	            })
242	        })?;
243	        let to = outcome.targets.get(id).cloned().ok_or_else(|| {
244	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
245	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
246	                field: "version",
247	            })
248	        })?;
249	
250	        let mut writes = Vec::new();
251	        for decl in &pkg.manifests {
252	            if decl.role == callisto_model::ManifestRole::Canonical {
253	                writes.push(VersionWriteTarget::Manifest(decl.path.clone()));
254	            }
255	        }
256	
257	        bumps.push(PlannedBump {
258	            package: id.clone(),
259	            from: from.clone(),
260	            to: to.clone(),
261	            severity: sev,
262	            governed_by: outcome.governed_by.get(id).cloned(),
263	            reason: outcome.reasons.get(id).cloned(),
264	            writes,
265	        });
266	
267	        if let Some(ch_path) = &pkg.changelog {
268	            let mut input = match agg.changelog_inputs.get(id).cloned() {
269	                Some(mut agg_input) => {
270	                    // Real changeset data: use it, but set the resolved target version.
271	                    agg_input.from = from.clone();
272	                    agg_input.to = Some(to.clone());
273	                    if let Some(reason) = outcome.reasons.get(id)
274	                        && let Some(source) = map_reason_to_change_source(reason, id, &to, &outcome, &agg)
275	                    {
276	                        agg_input.entries.push(ChangelogEntry { severity: sev, source });
277	                    }
278	                    agg_input.entries.extend(dependency_update_entries(id, sev, &outcome));
279	                    agg_input
280	                }
281	                _ => {
282	                    // No changeset drove this bump (cascade, group, inference, pre-release).
283	                    // Synthesize a single entry describing the reason so that render_section()
284	                    // never receives an empty entries list (which returns EmptyInput).
285	                    let mut entries: Vec<ChangelogEntry> = outcome
286	                        .reasons
287	                        .get(id)
288	                        .and_then(|r| map_reason_to_change_source(r, id, &to, &outcome, &agg))
289	                        .map(|source| ChangelogEntry { severity: sev, source })
290	                        .into_iter()
291	                        .collect();
292	                    entries.extend(dependency_update_entries(id, sev, &outcome));
293	                    if entries.is_empty() {
294	                        let source = ChangeSource::Changeset {
295	                            filename: String::new(),
296	                            summary: format!(
297	                                "Version bump ({})",
298	                                match sev {
299	                                    Severity::Major => "major",
300	                                    Severity::Minor => "minor",
301	                                    Severity::Patch => "patch",
302	                                    Severity::None => "none",
303	                                }
304	                            ),
305	                        };
306	                        entries.push(ChangelogEntry { severity: sev, source });
307	                    }
308	                    ChangelogInput {
309	                        style: ChangelogStyle::default(),
310	                        package: id.clone(),
311	                        from: from.clone(),
312	                        to: Some(to.clone()),
313	                        entries,
314	                    }
315	                }
316	            };
317	
318	            input.style = changelog_style(ws, repository.as_ref(), tags, id, &from, &to, date);
319	
320	            if let Some(group_name) = group_check
321	                .new_members
322	                .iter()
323	                .find(|(_, members)| members.contains(id))
324	                .map(|(name, _)| name.clone())
325	            {
326	                input.entries.push(ChangelogEntry {
327	                    severity: sev,
328	                    source: ChangeSource::NewGroupMember { group: group_name },
329	                });
330	            }
331	
332	            changelog_writes.push(crate::plan::ChangelogWrite {
333	                changelog_path: ch_path.clone(),
334	                input,
335	            });
336	        }
337	    }
338	
339	    let is_pre_mode = pre_state
340	        .as_ref()
341	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
342	        .unwrap_or(false);
343	    // In pre mode a changeset already recorded in pre.json is not pending: a rerun plans nothing for it.
344	    let nothing_pending = if is_pre_mode {
345	        agg.new_pre_changesets.is_empty()
346	    } else {
347	        agg.consumed.is_empty()
348	    };
349	
350	    // Reading the changesets comes first: an entry that names no package leaves its changeset on disk.
351	    let mut diagnostics = agg.diagnostics.clone();
352	    diagnostics.extend(outcome.diagnostics);
353	    diagnostics.extend(group_check.diagnostics);
354	    // A bump inferred from commits that survived aggregation is a plan, so "no changesets" would contradict it.
355	    if nothing_pending
356	        && !agg
357	            .named_by
358	            .values()
359	            .any(|named_by| *named_by == crate::aggregate::NamedBy::Inference)
360	        && !opts.allow_empty_changesets
361	        && !ws.config.validation.allow_empty_changesets
362	    {
363	        diagnostics.push(callisto_model::Diagnostic {
364	            code: callisto_model::DiagnosticCode::EmptyChangeset,
365	            severity: callisto_model::DiagnosticSeverity::Warning,
366	            message: "No pending changesets found in workspace".to_string(),
367	            package: None,
368	            path: None,
369	            escalated_by: Some(callisto_model::StrictFlag::Strict),
370	            governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
371	        });
372	    }
373	
374	    escalate(&mut diagnostics, opts.strict);
375	
376	    let (pre_state_update, delete_pre_json) = if let Some(mut state) = pre_state {
377	        if state.mode == callisto_model::format::PreMode::Exit {
378	            (None, Some(ws.config.pre_json_path()))
379	        } else {
380	            // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
381	            for id in &agg.new_pre_changesets {
382	                if !state.changesets.iter().any(|s| s == id) {
383	                    state.changesets.push(id.clone());
384	                }
385	            }
386	            (Some(state), None)
387	        }
388	    } else {
389	        (None, None)
390	    };
391	
392	    let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
393	    let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;
394	
395	    Ok(VersionPlan {
396	        bumps,
397	        rewrites: outcome.rewrites.into_values().collect(),
398	        platform_writes,
399	        optional_dep_updates,
400	        changelog_writes,
401	        consumed_changesets: agg.consumed,
402	        pre_state_update,
403	        pre_json_path: ws.config.pre_json_path(),
404	        pre_json_original_text,
405	        delete_pre_json,
406	        diagnostics,
407	    })
408	}
