410	/// The inputs of an interrupted run that changed in a way the run did not cause, so a resume must refuse (ADR 13).
411	///
412	/// `scratch` is the workspace loaded from the checkpoint's worktree and `plan` was made from it. The plan is applied
413	/// there, without a lockfile refresh, so the worktree becomes the tree a finished run leaves. Every file the plan was
414	/// derived from (the manifests the loader opened, `callisto.toml`, the changesets) and every file it writes must then be
415	/// on disk either as the checkpoint recorded it or as that expected tree has it, compared through Git's filters; a file
416	/// the expected tree lacks counts as the run's deletion only when the index lacks it too, so a changeset the user
417	/// deleted by hand is a change. `HEAD`, the tags and the Callisto version must match as well. `permit` writes only into
418	/// `scratch`.
419	pub fn resume_input_changes<R: CommandRunner, D: DependencyResolver>(
420	    ws: &Workspace<'_, R, D>,
421	    scratch: &Workspace<'_, R, D>,
422	    checkpoint: &callisto_model::vcs::Checkpoint,
423	    now: &callisto_model::vcs::CheckpointFacts,
424	    plan: &VersionPlan,
425	    runner: &R,
426	    permit: &callisto_model::ApplyPermit,
427	) -> Result<Vec<String>, GraphError> {
428	    let then = &checkpoint.facts;
429	    let mut changes = Vec::new();
430	    if now.head != then.head {
431	        changes.push(format!("`HEAD` moved from {} to {}", then.head, now.head));
432	    }
433	    if now.tags != then.tags {
434	        changes.push("tags changed".to_string());
435	    }
436	    if now.workspace != then.workspace {
437	        changes.push(format!(
438	            "the checkpoint belongs to the workspace `{}`, not this one",
439	            then.workspace
440	        ));
441	    }
442	    if now.callisto_version != then.callisto_version {
443	        changes.push(format!(
444	            "Callisto changed from {} to {}",
445	            then.callisto_version, now.callisto_version
446	        ));
447	    }
448	
449	    let apply_opts = crate::apply::ApplyOptions {
450	        refresh_lockfiles: false,
451	        transient: false,
452	    };
453	    crate::apply::apply_version_plan(&scratch.root, plan, runner, &apply_opts, permit)?;
454	
455	    let git = ws.git_access();
456	    let expected = scratch.git_access();
457	    let rev = checkpoint.commit.as_str();
458	
459	    let mut inputs: BTreeSet<std::path::PathBuf> = ws.manifest_cache.borrow().keys().cloned().collect();
460	    inputs.insert(std::path::PathBuf::from("callisto.toml"));
461	    // Discovery reads these to decide which directories are packages, and some of them without opening a manifest.
462	    inputs.extend(git.files_named(
463	        rev,
464	        &["pnpm-workspace.yaml", "package.json", "Cargo.toml", "pyproject.toml"],
465	    )?);
466	    inputs.extend(crate::apply::written_paths(plan));
467	    let dir = &ws.config.changesets_dir;
468	    inputs.extend(git.files_at(rev, dir)?);
469	    if let Ok(entries) = std::fs::read_dir(ws.root.join(dir)) {
470	        inputs.extend(
471	            entries
472	                .flatten()
473	                .filter(|entry| entry.path().is_file())
474	                .map(|entry| dir.join(entry.file_name())),
475	        );
476	    }
477	    for path in &inputs {
478	        let current = git.file_hash(path)?;
479	        if current == git.blob_hash_at(rev, path)? {
480	            continue;
481	        }
482	        // The run unstages a file before it deletes it, so a file that is gone but still staged was deleted by hand.
483	        let run_output = current == expected.file_hash(path)? && !(current.is_none() && git.is_staged(path)?);
484	        if !run_output {
485	            changes.push(format!("`{}` changed", path.display()));
486	        }
487	    }
488	    Ok(changes)
489	}
