491	/// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
492	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
493	    let head = match ws.git_access().head_sha() {
494	        Ok(head) => head,
495	        Err(error) => {
496	            let output = ws
497	                .runner
498	                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
499	                .map_err(GraphError::Command)?;
500	            match output.exit_code {
501	                Some(1) => return Ok(()),
502	                Some(0) => return Err(error.into()),
503	                exit_code => {
504	                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
505	                        program: "git".to_string(),
506	                        exit_code,
507	                        stderr: output.stderr,
508	                    }))
509	                }
510	            }
511	        }
512	    };
513	    let head = head.as_str();
514	
515	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
516	    let pre_mode = {
517	        let path = ws.root.join(ws.config.pre_json_path());
518	        let text = callisto_model::strict_fs::read_optional(&path).map_err(|e| GraphError::PreJsonRead {
519	            path: path.clone(),
520	            message: e.to_string(),
521	        })?;
522	        if let Some(text) = text {
523	            let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
524	            Some(state.mode)
525	        } else {
526	            None
527	        }
528	    };
529	    let in_pre_release_cycle = pre_mode == Some(callisto_model::format::PreMode::Pre);
530	
531	    let changed = SourceChanges::since(ws, head)?;
532	    // The paths that can set each manifest's version are found once and used by both passes below.
533	    let mut sources: HashMap<std::path::PathBuf, Vec<String>> = HashMap::new();
534	    let staged_manifests = if in_pre_release_cycle {
535	        BTreeSet::new()
536	    } else {
537	        canonical_manifest_staged_paths(ws, head, &changed, &mut sources)?
538	    };
539	    let pending = !in_pre_release_cycle
540	        && (head_has_pending_changeset(ws, head)?
541	            || working_tree_has_pending_changeset(ws)?
542	            || !staged_manifests.is_empty());
543	    if !pending {
544	        return Ok(());
545	    }
546	
547	    let head_texts = RefCell::new(HashMap::new());
548	    let index_texts = RefCell::new(HashMap::new());
549	    prefetch_head_manifests(ws, head, &head_texts)?;
550	    let mut head_reads = callisto_manifests::WorkspaceReads::default();
551	    let mut index_reads = callisto_manifests::WorkspaceReads::default();
552	    let base_versions = ws.base_versions()?;
553	    for pkg in ws.graph.packages() {
554	        let Some(disk) = base_versions.get(&pkg.id) else {
555	            continue;
556	        };
557	        for decl in pkg.canonical_manifests() {
558	            let path = super::release_decision::normalized_git_path(&decl.path)?;
559	            let Some(head_version) = manifest_version_at(ws, head, &path, &head_texts, &mut head_reads)? else {
560	                continue;
561	            };
562	            let index_path_changed = version_sources(ws, head, &changed, decl, &mut sources)?
563	                .iter()
564	                .any(|source| staged_manifests.contains(source));
565	            let index_version = if index_path_changed {
566	                manifest_version_in_index(ws, head, &path, &index_texts, &mut index_reads)?
567	            } else {
568	                None
569	            };
570	            let index_display = match &index_version {
571	                Some(version) => version.version.render().to_string(),
572	                None if index_path_changed => "absent".to_string(),
573	                None => head_version.version.render().to_string(),
574	            };
575	            let index_differs = index_path_changed
576	                && index_version
577	                    .as_ref()
578	                    .is_none_or(|version| version.version != head_version.version);
579	            let completing_prerelease = pre_mode == Some(callisto_model::format::PreMode::Exit)
580	                && disk.is_prerelease()
581	                && (!index_path_changed
582	                    || index_version
583	                        .as_ref()
584	                        .is_some_and(|version| version.version.is_prerelease()));
585	            if completing_prerelease {
586	                continue;
587	            }
588	            if *disk != head_version.version || index_differs {
589	                return Err(GraphError::PartialVersionRun {
590	                    path: head_version.authority,
591	                    disk: disk.clone(),
592	                    index: index_display,
593	                    head: head_version.version,
594	                });
595	            }
596	        }
597	    }
598	
599	    Ok(())
600	}
