602	/// Reads every canonical manifest at `head` in one `git cat-file --batch`, so the version reads that follow cost no
603	/// process each. A failed batch is not an error: those reads then run one at a time, as they always could.
604	fn prefetch_head_manifests<R: CommandRunner, D: DependencyResolver>(
605	    ws: &Workspace<'_, R, D>,
606	    head: &str,
607	    texts: &ManifestTexts,
608	) -> Result<(), GraphError> {
609	    let mut paths = BTreeSet::new();
610	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
611	        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
612	    }
613	    let objects: Vec<String> = paths
614	        .iter()
615	        .map(|path| super::release_decision::object_at(head, path))
616	        .collect();
617	    let Ok(blobs) = batch_blobs(ws.runner, &ws.root, &objects) else {
618	        return Ok(());
619	    };
620	    let mut texts = texts.borrow_mut();
621	    for (path, blob) in paths.into_iter().zip(blobs) {
622	        texts.insert(
623	            path,
624	            match blob {
625	                BatchBlob::Blob(text) => Some(text),
626	                BatchBlob::Missing => None,
627	            },
628	        );
629	    }
630	    Ok(())
631	}
