633	/// True when an untracked or tracked changeset remains in the configured directory on disk.
634	fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
635	    ws: &Workspace<'_, R, D>,
636	) -> Result<bool, GraphError> {
637	    let dir = ws.root.join(&ws.config.changesets_dir);
