645	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
646	fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
647	    ws: &Workspace<'_, R, D>,
648	    head: &str,
649	    changed: &SourceChanges,
650	    sources: &mut HashMap<std::path::PathBuf, Vec<String>>,
651	) -> Result<BTreeSet<String>, GraphError> {
652	    let mut paths = BTreeSet::new();
653	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
654	        paths.extend(version_sources(ws, head, changed, decl, sources)?);
