660	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
661	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
662	    ws: &Workspace<'_, R, D>,
663	    spec: &str,
664	) -> Result<bool, GraphError> {
665	    let output = ws
666	        .runner
667	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
668	        .map_err(GraphError::Command)?;
669	    match output.exit_code {
670	        Some(0) => Ok(true),
671	        Some(1) => Ok(false),
672	        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
673	            program: "git".to_string(),
674	            exit_code,
675	            stderr: output.stderr,
676	        })),
677	    }
678	}
