680	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
681	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
682	    ws: &Workspace<'_, R, D>,
683	    head: &str,
684	) -> Result<bool, GraphError> {
685	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
686	    let spec = super::release_decision::object_at(head, &dir);
687	    if !head_object_exists(ws, &spec)? {
688	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
689	        return Ok(false);
690	    }
691	    let output = ws
692	        .runner
693	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
694	        .map_err(GraphError::Command)?;
695	    if !output.success() {
696	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
697	            program: "git".to_string(),
698	            exit_code: output.exit_code,
699	            stderr: output.stderr,
700	        }));
701	    }
702	    Ok(output.stdout.lines().any(|name| {
703	        let name = name.trim();
704	        name.ends_with(".md") && name != "README.md"
705	    }))
706	}
