753	/// The paths that differ from `HEAD` in the working tree or the index, and those that differ in the index alone.
754	struct SourceChanges {
755	    changed: BTreeSet<String>,
756	    staged: BTreeSet<String>,
757	}
758	
759	impl SourceChanges {
760	    fn since<R: CommandRunner, D: DependencyResolver>(
761	        ws: &Workspace<'_, R, D>,
762	        head: &str,
763	    ) -> Result<Self, GraphError> {
764	        let mut changed = BTreeSet::new();
765	        let mut staged = BTreeSet::new();
766	        let working_tree = vec!["diff", "--name-only", "-z", "--relative", head];
767	        let index = vec!["diff", "--cached", "--name-only", "-z", "--relative", head];
768	        for (args, is_index) in [(working_tree, false), (index, true)] {
769	            let output = ws.runner.run("git", &args, &ws.root).map_err(GraphError::Command)?;
770	            if !output.success() {
771	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
772	                    program: "git".to_string(),
773	                    exit_code: output.exit_code,
774	                    stderr: output.stderr,
775	                }));
776	            }
777	            let paths = output
778	                .stdout
779	                .split('\0')
780	                .filter(|path| !path.is_empty())
781	                .map(str::to_owned);
782	            if is_index {
783	                let paths: Vec<String> = paths.collect();
784	                staged.extend(paths.iter().cloned());
785	                changed.extend(paths);
786	            } else {
787	                changed.extend(paths);
788	            }
789	        }
790	        Ok(SourceChanges { changed, staged })
791	    }
792	}
