794	/// [`version_source_paths`], remembered per manifest.
795	fn version_sources<R: CommandRunner, D: DependencyResolver>(
796	    ws: &Workspace<'_, R, D>,
797	    head: &str,
798	    changed: &SourceChanges,
799	    decl: &callisto_model::ManifestDecl,
800	    memo: &mut HashMap<std::path::PathBuf, Vec<String>>,
801	) -> Result<Vec<String>, GraphError> {
802	    if let Some(known) = memo.get(&decl.path) {
803	        return Ok(known.clone());
804	    }
805	    let sources = version_source_paths(ws, head, changed, decl)?;
806	    memo.insert(decl.path.clone(), sources.clone());
807	    Ok(sources)
808	}
809	
810	/// Every path whose staged change could alter the effective version of `decl`: its own manifest and, for Cargo, each
811	/// manifest that could be the workspace root it inherits from. That includes the workspace the package names in the
812	/// working tree, and, when its own manifest has changed since `HEAD`, the one it named at `HEAD` and in the index.
813	fn version_source_paths<R: CommandRunner, D: DependencyResolver>(
814	    ws: &Workspace<'_, R, D>,
815	    head: &str,
816	    changed: &SourceChanges,
817	    decl: &callisto_model::ManifestDecl,
818	) -> Result<Vec<String>, GraphError> {
819	    let own = super::release_decision::normalized_git_path(&decl.path)?;
820	    let mut sources = vec![own.clone()];
821	    if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
822	        for candidate in callisto_manifests::workspace_manifest_candidates(&ws.root, &decl.path)? {
823	            sources.push(super::release_decision::normalized_git_path(&candidate)?);
824	        }
825	        if changed.changed.contains(&own) {
826	            for text in [manifest_blob_at(ws, head, &own)?, manifest_blob_in_index(ws, &own)?]
827	                .into_iter()
828	                .flatten()
829	            {
830	                if let Some(named) = callisto_manifests::named_workspace_manifest(&decl.path, &text)? {
831	                    sources.push(super::release_decision::normalized_git_path(&named)?);
832	                }
833	            }
834	        }
835	    }
836	    Ok(sources)
837	}
