839	/// Manifest text by normalized path, fetched at most once per path.
840	type ManifestTexts = RefCell<HashMap<String, Option<String>>>;
841	
842	fn cached_text(
843	    texts: &ManifestTexts,
844	    path: &std::path::Path,
845	    fetch: impl FnOnce(&str) -> Result<Option<String>, GraphError>,
846	) -> Result<Option<String>, GraphError> {
847	    let key = super::release_decision::normalized_git_path(path)?;
848	    if let Some(text) = texts.borrow().get(&key) {
849	        return Ok(text.clone());
850	    }
851	    let text = fetch(&key)?;
852	    texts.borrow_mut().insert(key, text.clone());
853	    Ok(text)
854	}
