856	fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
857	    ws: &Workspace<'_, R, D>,
858	    head: &str,
859	    path: &str,
860	    texts: &ManifestTexts,
861	    reads: &mut callisto_manifests::WorkspaceReads,
862	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
863	    let path = std::path::Path::new(path);
864	    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
865	        return Ok(None);
866	    };
867	    let at_head = |other: &std::path::Path| cached_text(texts, other, |key| manifest_blob_at(ws, head, key));
868	    let Some(source) = at_head(path)? else {
869	        return Ok(None);
870	    };
871	    callisto_manifests::read_effective_version(format, &source, path, reads, at_head)
872	}
873	
874	/// The version `path` has in the index; manifests it inherits from that the index lacks are read from `head`.
875	fn manifest_version_in_index<R: CommandRunner, D: DependencyResolver>(
876	    ws: &Workspace<'_, R, D>,
877	    head: &str,
878	    path: &str,
879	    texts: &ManifestTexts,
880	    reads: &mut callisto_manifests::WorkspaceReads,
881	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
882	    let manifest_path = std::path::Path::new(path);
883	    let Ok(format) = callisto_model::ManifestFormat::from_path(manifest_path) else {
884	        return Ok(None);
885	    };
886	    let Some(source) = manifest_blob_in_index(ws, path)? else {
887	        return Ok(None);
888	    };
889	    let in_index_or_head = |other: &std::path::Path| {
890	        cached_text(texts, other, |key| match manifest_blob_in_index(ws, key)? {
891	            Some(text) => Ok(Some(text)),
892	            None => manifest_blob_at(ws, head, key),
893	        })
894	    };
895	    callisto_manifests::read_effective_version(format, &source, manifest_path, reads, in_index_or_head)
896	}
