898	/// Platform manifest version writes and owner `optionalDependencies` pin updates
899	/// for every owner with a target version in `targets`. Sources: each owner's
900	/// attached platform manifests, plus `[[fixed-group]]`
901	/// platform members.
902	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
903	    ws: &Workspace<'_, R, D>,
904	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
905	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
906	    let open_ctx = OpenContext::for_workspace_root(&ws.root)?;
907	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
908	
909	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
910	    for pkg in ws.graph.packages() {
911	        members.extend(
912	            ws.identity
913	                .attached_platforms(pkg)
914	                .map(|(name, path)| (&pkg.id, path, name)),
915	        );
916	    }
917	    for group in ws.config.groups.fixed.values() {
918	        for member in group.members(GroupMemberKind::PlatformManifest) {
919	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
920	                members.push((owner, path, name));
921	            }
922	        }
923	    }
924	
925	    let mut seen = HashSet::new();
926	    let mut platform_writes = Vec::new();
927	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
928	        std::collections::BTreeMap::new();
929	    for (owner, path, name) in members {
930	        let Some(to) = targets.get(owner) else {
931	            continue;
932	        };
933	        if !seen.insert(path) {
934	            continue;
935	        }
936	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
937	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
938	        let handle = open(&decl, &open_ctx)?;
939	        let current = handle.current_version()?;
940	        platform_writes.push(PlatformWrite {
941	            manifest: path.to_path_buf(),
942	            version: to.clone(),
943	            from: current,
944	        });
945	
946	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
947	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
948	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
949	            let owner_manifest_decl =
950	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
951	            // Cached: owner manifest is shared across every platform target under it.
952	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
953	            if owner_handle
954	                .iter_dependencies()
955	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
956	            {
957	                optional_dep_map
958	                    .entry(owner_decl.path.clone())
959	                    .or_default()
960	                    .push((name.to_string(), to.clone()));
961	                break;
962	            }
963	        }
964	    }
965	    let optional_dep_updates = optional_dep_map
966	        .into_iter()
967	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
968	        .collect();
969	    Ok((platform_writes, optional_dep_updates))
970	}
